/bin/sh -lc "python - <<'PY'
import json, os, tempfile
with open('/spec/formal-context.json') as f:
    source = json.load(f)
result = {
    'schema_version': 1,
    'candidate_hash': source['candidate_hash'],
    'status': 'complete',
    'statement': 'For every model consisting of a real number u >= 0 and a function r: R -> R such that for every real z there exists a real delta with |delta| <= u and r(z) = z(1 + delta), every finite list c of real coefficients, and every real x, the recursively rounded evaluation Q(model,c,x) differs from the exact polynomial evaluation P(c,x) by at most E(c,x,u). The constructions P, Q, and E are the recursions specified below; the theorem bounds the error of precisely that Q using precisely that E.',
    'targets': [{
        'name': 'Research.FloatingPoint.Horner.forward_error',
        'statement': 'For every model m in Research.FloatingPoint.Model, every finite list c of real numbers, and every x in R, |Q(m,c,x) - P(c,x)| <= E(c,x,u(m)). Here m supplies u(m) in R with 0 <= u(m), and r = round(m): R -> R satisfying: for every z in R there exists delta in R such that |delta| <= u(m) and r(z) = z(1 + delta). P is the exact recursive evaluation, Q applies r separately to each product and subsequent sum, and E is the recursive bound defined below, evaluated at the same list and x and at the model parameter u(m). There are no additional hypotheses on c or x or any upper bound on u(m).'
    }],
    'constructions': [
        {
            'name': 'Research.FloatingPoint.Horner.P',
            'description': 'A function from finite lists of real numbers and real x to R. For every x in R, P([],x) = 0. For every a in R, finite real list t, and x in R, P(a::t,x) = a + x P(t,x), where a::t denotes the list with head a and tail t. Thus for c = [a_0,...,a_(n-1)] of any length n >= 0, P(c,x) = sum over 0 <= i < n of a_i x"'^i, with the empty sum equal to zero. The head coefficient is the constant term; all operations here are exact real operations.'"'
        },
        {
            'name': 'Research.FloatingPoint.Horner.Q',
            'description': 'A function taking a model m, a finite real coefficient list c, and real x, with real output. Write r = round(m). For every m and real x, Q(m,[],x) = 0. For every m, a in R, finite real list t, and x in R, Q(m,a::t,x) = r(a + r(x Q(m,t,x))). It evaluates the tail first, multiplies its rounded result by x, applies r to that product, adds the head a, and applies r again. There are two applications of r at every nonempty list node, including the final coefficient node whose tail result is zero. Coefficients and x are real inputs with no separate input-rounding operation. The model constrains r only through its stated relative-error property; no particular machine format or rounding rule is supplied.'
        },
        {
            'name': 'Research.FloatingPoint.Horner.E',
            'description': 'A real-valued function E(c,x,u) defined for every finite real list c and every pair x,u in R, even when u is negative. E([],x,u) = 0. For every real a,x,u and finite real list t, set v = P(t,x) and e = E(t,x,u); then E(a::t,x,u) = u |a + x v| + (1 + u)(u |x v| + (1 + u)|x| e). This construction uses exact tail values P(t,x), absolute values, and the recursively accumulated e; it does not run Q or use a rounding function. The theorem uses this expression only at u = u(m) >= 0 as an upper bound on |Q(m,c,x) - P(c,x)|.'
        }
    ],
    'assumptions': [
        'A model consists of a real parameter u, a proof that 0 <= u, a function round: R -> R, and the property that for every z in R there exists delta in R with |delta| <= u and round(z) = z(1 + delta). The existential delta may depend on z; no common delta for all z is assumed.',
        'The target universally quantifies over all such models, all finite lists of real coefficients (including the empty list), and all real evaluation points x. There is no bound on list length, coefficient sizes, or |x|, and no upper bound on u.',
        'List order is the order used in the stated recursions: a head coefficient a is added to x times the tail evaluation. Exact arithmetic, inequalities, and absolute values are those of the real numbers.'
    ],
    'missing_context': []
}
assert [x['name'] for x in result['targets']] == source['targets']
assert [x['name'] for x in result['constructions']] == source['construction_names']
assert set(result) == {'schema_version','candidate_hash','status','statement','targets','constructions','assumptions','missing_context'}
os.makedirs('/output', exist_ok=True)
fd, path = tempfile.mkstemp(prefix='.translation-', suffix='.json', dir='/output')
try:
    with os.fdopen(fd, 'w') as f:
        json.dump(result, f, indent=2, ensure_ascii=False)
        f.write('\\n')
        f.flush()
        os.fsync(f.fileno())
    os.replace(path, '/output/translation.json')
except BaseException:
    if os.path.exists(path):
        os.unlink(path)
    raise
print('Saved /output/translation.json atomically; status complete; 1 target and 3 constructions.')
PY"

